// Friendly names for the types generated from contract/openapi.yaml.
// schema.d.ts is generated by `npm run contract:sync` (or `npm run contract:types`). Never edit it by hand.
import type { components } from './schema';

type S = components['schemas'];

export type ApiErrorBody = S['Error'];
export type ApiErrorCode = S['Error']['code'];
export type FieldIssue = S['FieldIssue'];
export type Role = S['Role'];
export type OrganisationType = S['OrganisationType'];
export type BloodGroup = S['BloodGroup'];
export type Rhesus = S['Rhesus'];
export type Component = S['Component'];
export type Urgency = S['Urgency'];
export type UnitState = S['UnitState'];
export type RequestState = S['RequestState'];
export type ReservationStatus = S['ReservationStatus'];
export type SessionCreate = S['SessionCreate'];
export type Session = S['Session'];
export type User = S['User'];
export type Organisation = S['Organisation'];
export type UnitCreate = S['UnitCreate'];
export type Unit = S['Unit'];
export type UnitPage = S['UnitPage'];
export type Availability = S['Availability'];
export type AvailabilityRow = S['AvailabilityRow'];
export type BloodRequestCreate = S['BloodRequestCreate'];
export type Declination = S['Declination'];
export type Reservation = S['Reservation'];
export type HistoryEntry = S['HistoryEntry'];
export type BloodRequest = S['BloodRequest'];
export type BloodRequestPage = S['BloodRequestPage'];

/** The user's bank or hospital (null for donors and the administrator). */
export function userOrganisation(user: User): Organisation | null {
  return (user.organisation ?? null) as unknown as Organisation | null;
}

// Query parameters, written as type aliases (not interfaces) so they fit the client's query map.
export type UnitQuery = {
  bankId?: string;
  state?: UnitState;
  bloodGroup?: BloodGroup;
  rhesus?: Rhesus;
  component?: Component;
  page?: number;
  size?: number;
};

export type AvailabilityQuery = {
  bloodGroup?: BloodGroup;
  rhesus?: Rhesus;
  component?: Component;
  bankId?: string;
  area?: string;
};

export type RequestQuery = {
  state?: RequestState;
  page?: number;
  size?: number;
};

export type OrganisationQuery = {
  type?: OrganisationType;
  area?: string;
};
